11	 * step runs the request has already passed {@link CheckOwnerIdentityUnique}, so its
12	 * {@code identityKey} is unique. This step records a weaker signal: an existing (non-deleted)
13	 * owner whose <em>identityKey differs</em> yet whose {@code soundex(lastName)} and {@code postcode}
14	 * both match. The typical case is the same household with a different telephone: because the
15	 * telephone is part of the identity key, such an owner is no longer a hard duplicate, so it is
16	 * created but flagged.
17	 *
18	 * <p>The matched owner is created with {@code possibleDuplicate = true} and
19	 * {@code possibleDuplicateOf} set to the matching owner's id (the lowest matching id when several
20	 * match). When nothing matches, {@code possibleDuplicate} is {@code false} and
21	 * {@code possibleDuplicateOf} stays absent.
22	 *
23	 * <p>Runs after {@link CheckOwnerIdentityUnique} and before {@link SaveOwner} (so the new owner is
24	 * not yet among {@code findAll()} and cannot match itself), mutating the built {@link Owner} in
25	 * place.
26	 */
27	public class CheckPossibleDuplicate {
28	
29	    public void service(@Val Owner built, OwnerRepository ownerRepository) {
30	        String identityKey = IdentityKey.of(built);
31	        Integer matchId = null;
32	        for (Owner existing : ownerRepository.findAll()) {
33	            if (Boolean.TRUE.equals(existing.getDeleted())) {
34	                continue; // a soft-deleted owner is not a suspected duplicate
35	            }
36	            if (!identityKey.equals(IdentityKey.of(existing))
37	                    && sameSoundex(built, existing) && samePostcode(built, existing)) {
38	                Integer id = existing.getId();
39	                if (id != null && (matchId == null || id < matchId)) {
40	                    matchId = id;
41	                }
42	            }
43	        }
44	        built.setPossibleDuplicate(matchId != null);
45	        built.setPossibleDuplicateOf(matchId);
46	    }
47	
48	    private static boolean sameSoundex(Owner a, Owner b) {
49	        String sa = Soundex.of(a.getLastName());
50	        return !sa.isEmpty() && sa.equals(Soundex.of(b.getLastName()));
51	    }
52	
53	    private static boolean samePostcode(Owner a, Owner b) {
54	        String pa = a.getPostcode();
55	        String pb = b.getPostcode();
