7	/**
8	 * Derives an owner's locality (canonical region). Locality now flows from the owner's
9	 * region-and-hash {@code memberId}: the REGION prefix of {@code '<REGION><FY><HASH8><CHK>'} is the
10	 * canonical region (the leading run of letters before the two-digit fiscal year), so locality and
11	 * the identity always agree. When the memberId has not been assigned it falls back to deriving the
12	 * region directly. In that direct derivation the postcode is preferred: a 4-digit postcode falling
13	 * in a known region's range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) fixes the region, which
14	 * disambiguates cities that share a name; only when the postcode is absent or in no known range
15	 * does it fall back to the fixed city-to-region table. Kept out of {@link OwnerMapper} so MapStruct
16	 * does not mistake the helper for an implicit mapping method and apply it to every string property.
17	 */
18	public final class Locality {
19	
20	    /** City -> canonical region; anything not listed derives locality "UNKNOWN". */
21	    private static final Map<String, String> CITY_REGION = Map.of(
22	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
23	
24	    /** Region -> inclusive 4-digit postcode range {low, high}. */
25	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
26	        "NSW", new int[] {2000, 2099},
27	        "VIC", new int[] {3000, 3099},
28	        "QLD", new int[] {4000, 4099});
29	
30	    private Locality() {
31	    }
32	
33	    /**
34	     * The owner's locality, read from the REGION prefix of its region-and-hash memberId so it
35	     * agrees with the identity. The REGION is the leading run of letters before the two-digit
36	     * fiscal year. Falls back to deriving the region from the city and postcode when the memberId
37	     * has not been assigned (e.g. records that never went through create).
38	     */
39	    public static String of(Owner owner) {
40	        String memberId = owner.getMemberId();
41	        if (memberId != null) {
42	            int i = 0;
43	            while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
44	                i++;
45	            }
46	            if (i > 0) {
47	                return memberId.substring(0, i);
48	            }
49	        }
50	        return of(owner.getCity(), owner.getPostcode());
51	    }
52	
53	    /**
54	     * The canonical region, preferring the postcode range and falling back to the
55	     * city-to-region table. Returns "UNKNOWN" when neither resolves a region.
56	     */
57	    public static String of(String city, String postcode) {
58	        String byPostcode = regionForPostcode(postcode);
59	        return byPostcode != null ? byPostcode : of(city);
60	    }
61	
62	    /** The canonical region for {@code city}, or "UNKNOWN" when it is not in the table. */
63	    public static String of(String city) {
64	        return city == null ? "UNKNOWN" : CITY_REGION.getOrDefault(city, "UNKNOWN");
65	    }
66	
67	    /**
68	     * The region whose range contains {@code postcode}, or {@code null} when the postcode
69	     * is absent, non-numeric, or in no known range.
70	     */
71	    private static String regionForPostcode(String postcode) {
72	        if (postcode == null || postcode.isBlank()) {
73	            return null;
74	        }
75	        int value;
76	        try {
77	            value = Integer.parseInt(postcode.trim());
78	        }
79	        catch (NumberFormatException ex) {
80	            return null;
81	        }
82	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
83	            int[] range = entry.getValue();
84	            if (value >= range[0] && value <= range[1]) {
85	                return entry.getKey();
86	            }
87	        }
88	        return null;
89	    }
